function client(){
var D=window.D,JOB=D.job,app=document.getElementById('app'),DATA=null,FILTER='open',Q='',LOGO=null;
var STS=['Draft','Sent','Answered','Closed'];
function s(v){return v==null?'':String(v);}
function e(t){return s(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
function dmy(d){var m=s(d).match(/^(\d{4})-(\d{2})-(\d{2})/);return m?m[3]+'/'+m[2]+'/'+m[1]:s(d);}
function today(){var d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function plus(n){var d=new Date();d.setDate(d.getDate()+n);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,10);}
function who(){var x='';try{var m=JSON.parse(localStorage.getItem('cbs_me')||'null');if(m&&m.name)x=m.name;}catch(z){}if(!x){try{x=localStorage.getItem('cbs_name')||'';}catch(z){}}if(!x){x=(prompt('Your name:')||'').trim();if(x){try{localStorage.setItem('cbs_name',x);}catch(z){}}}return x;}
function post(body){var by=who();if(!by)return Promise.resolve({ok:false,message:'',cancel:true});body.job=JOB;body.by=by;
 return fetch('/webhook/cbs-rfi-act',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){if(!r.ok)throw 0;return r.json();}).catch(function(){return {ok:false,message:'Could not save. Check your connection and try again.'};});}
function load(){return fetch('/webhook/cbs-rfis-data?job='+encodeURIComponent(JOB),{cache:'no-store'}).then(function(r){return r.json();}).then(function(d){DATA=d;if(!D.site&&d.site){D.site=d.site;D.client=d.client;var hp=document.querySelector('header p');if(hp)hp.textContent=[d.site,d.client].filter(Boolean).join(' \u00b7 ');}render();}).catch(function(){app.innerHTML='<div class="empty">Could not load the RFIs. Refresh to try again.</div>';});}
function dlg(html){var o=document.createElement('div');o.className='ov';o.innerHTML='<div class="dlg">'+html+'</div>';document.body.appendChild(o);o.close=function(){o.remove();};return o;}
function guard(o,isDirty){o.addEventListener('click',function(ev){if(ev.target!==o)return;if(isDirty&&isDirty()&&!confirm('Close without saving your changes?'))return;o.close();});}
function rows(){return (DATA&&DATA.rows)||[];}
function isOpen(r){return r.status==='Draft'||r.status==='Sent';}
function vis(){var q=Q.toLowerCase();return rows().filter(function(r){if(FILTER==='open'&&!isOpen(r))return false;if(FILTER==='overdue'&&!r.overdue)return false;if(FILTER!=='all'&&FILTER!=='open'&&FILTER!=='overdue'&&s(r.status)!==FILTER)return false;if(!q)return true;return [r.rfi_no,r.subject,r.question,r.sent_to,r.response].join(' ').toLowerCase().indexOf(q)>-1;});}
function render(){var C=DATA.counts||{},h='';
 var open=(C.Draft||0)+(C.Sent||0);
 h+='<div class="strip"><div class="pst"><b>'+(C.Draft||0)+'</b><span>Drafts</span></div><div class="pst'+(DATA.overdue?' warn':'')+'"><b>'+(C.Sent||0)+'</b><span>Awaiting reply'+(DATA.overdue?' ('+DATA.overdue+' overdue)':'')+'</span></div><div class="pst ok"><b>'+(C.Answered||0)+'</b><span>Answered</span></div><div class="pst"><b>'+(C.Closed||0)+'</b><span>Closed</span></div></div>';
 h+='<div class="tools"><button class="btn" id="add">+ New RFI</button><button class="btn ghost" id="log">RFI log PDF</button></div>';
 var F=[['open','Open',open],['overdue','Overdue',DATA.overdue||0],['all','All',rows().length]].concat(STS.map(function(k){return [k,k,C[k]||0];}));
 h+='<div class="flt">'+F.map(function(f){return '<button data-f="'+f[0]+'" class="'+(FILTER===f[0]?'on':'')+'">'+f[1]+' ('+f[2]+')</button>';}).join('')+'</div>';
 h+='<input class="srch" id="q" placeholder="Search RFIs" value="'+e(Q)+'">';
 var L=vis();
 if(!rows().length)h+='<div class="empty">No RFIs on this job yet. Tap + New RFI to raise one.</div>';
 else if(!L.length)h+='<div class="empty">Nothing here'+(FILTER==='open'?' \u2013 no open RFIs. Tap All to see the rest.':'.')+'</div>';
 L.forEach(function(r){var st=s(r.status)||'Draft';
  h+='<div class="card" data-id="'+r.id+'"><div class="t">'+e(r.rfi_no)+' \u00b7 '+e(r.subject)+'<span class="tag '+e(st)+'">'+e(st)+'</span>'+(r.overdue?'<span class="tag od">Overdue</span>':'')+'</div>'
  +'<div class="m">'+[r.sent_to?'To '+e(r.sent_to):'No recipient yet',r.sent_on?'sent '+dmy(r.sent_on):'',r.needed_by?'needed by '+dmy(r.needed_by):'',r.responded_on?'answered '+dmy(r.responded_on):''].filter(Boolean).join(' \u00b7 ')+'</div>'
  +'<div class="ds">'+e(r.question)+'</div>'
  +(r.response?'<div class="ans"><b>Answer:</b> '+e(r.response)+'</div>':'')
  +'<div class="b">'
  +(st==='Draft'?'<button class="btn sm" data-a="send">Mark sent</button>':'')
  +(st==='Sent'?'<button class="btn sm" data-a="answer">Record answer</button>':'')
  +(st==='Answered'?'<button class="btn sm" data-a="close">Close</button><button class="btn ghost sm" data-a="ansedit">Edit answer</button><button class="btn ghost sm" data-a="more">Ask again</button>':'')
  +(st==='Closed'?'<button class="btn ghost sm" data-a="reopen">Reopen</button>':'')
  +(st==='Sent'?'<button class="btn ghost sm" data-a="back">Back to draft</button>':'')
  +((st==='Draft'||st==='Sent')?'<button class="btn ghost sm" data-a="mail">Email it</button>':'')
  +'<button class="btn ghost sm" data-a="edit">Edit</button><button class="btn ghost sm" data-a="pdf">RFI PDF</button><button class="btn red sm" data-a="del">Delete</button></div>'
  +(r.history?'<details><summary class="m" style="cursor:pointer">History</summary><div class="hist">'+e(r.history)+'</div></details>':'')+'</div>';});
 app.innerHTML=h;
 document.getElementById('add').onclick=function(){editDlg(null);};document.getElementById('log').onclick=logDlg;
 app.querySelectorAll('[data-f]').forEach(function(b){b.onclick=function(){FILTER=b.getAttribute('data-f');render();};});
 var qi=document.getElementById('q');qi.oninput=function(){Q=qi.value;var p=qi.selectionStart;render();var x=document.getElementById('q');x.focus();try{x.setSelectionRange(p,p);}catch(z){}};
 app.querySelectorAll('[data-a]').forEach(function(el){var id=el.closest('.card').getAttribute('data-id');var r=rows().filter(function(x){return String(x.id)===id;})[0];var a=el.getAttribute('data-a');
  el.onclick=function(){if(a==='edit')editDlg(r);else if(a==='send')sendDlg(r);else if(a==='answer')answerDlg(r,'Answered');else if(a==='ansedit')answerDlg(r,'edit');else if(a==='close')simple(r,'Closed','Close '+r.rfi_no+'?');else if(a==='reopen')simple(r,r.response?'Answered':'Sent','Reopen '+r.rfi_no+'?');else if(a==='back')simple(r,'Draft','Move '+r.rfi_no+' back to draft? The sent date is cleared.');else if(a==='more')simple(r,'Sent','Send '+r.rfi_no+' back to awaiting a reply? The current answer is moved into the history.');else if(a==='mail')mail(r);else if(a==='pdf')sheet(r);else if(a==='del')delR(r);};});}
function simple(r,st,q){if(!confirm(q))return;post({a:'status',id:r.id,status:st}).then(function(x){if(!x.ok&&!x.cancel)alert(x.message||'Could not save.');load();});}
function editDlg(r){r=r||{};var CT=DATA.contacts||[];
 var o=dlg('<h2>'+(r.id?'Edit '+e(r.rfi_no):'New RFI')+'</h2><label class="f">Subject</label><input type="text" id="fs" value="'+e(r.subject)+'" placeholder="e.g. Finish to rear elevation">'
 +'<label class="f">Question</label><textarea id="fq" style="min-height:140px" placeholder="What you need answered, with any drawing or location references">'+e(r.question)+'</textarea>'
 +'<label class="f">To</label>'+(CT.length?'<select id="fp"><option value="">Pick from Subcontractors and Suppliers, or type below\u2026</option>'+CT.map(function(c,i){return '<option value="'+i+'">'+e(c.label)+(c.email?' \u2013 '+e(c.email):'')+'</option>';}).join('')+'</select>':'')
 +'<div class="row2" style="margin-top:6px"><input type="text" id="ft" value="'+e(r.sent_to)+'" placeholder="Name or company"><input type="text" id="fe" value="'+e(r.sent_to_email)+'" placeholder="Email (optional)"></div>'
 +'<label class="f">Answer needed by</label><input type="date" id="fn" value="'+e(r.needed_by||(r.id?'':plus(7)))+'">'
 +'<div class="msg" id="fm"></div><div class="b"><button class="btn" id="fsv">Save</button><button class="btn ghost" id="fx">Cancel</button></div>');
 var fp=o.querySelector('#fp');if(fp)fp.onchange=function(){var c=CT[Number(fp.value)];if(!c)return;o.querySelector('#ft').value=c.label;o.querySelector('#fe').value=c.email||'';};
 var ids=['fs','fq','ft','fe','fn'],st=ids.map(function(i){return o.querySelector('#'+i).value;}).join('|');
 function dirty(){return ids.map(function(i){return o.querySelector('#'+i).value;}).join('|')!==st;}
 guard(o,dirty);o.querySelector('#fx').onclick=function(){if(dirty()&&!confirm('Close without saving your changes?'))return;o.close();};
 o.querySelector('#fsv').onclick=function(){var sj=o.querySelector('#fs').value.trim(),q=o.querySelector('#fq').value.trim();if(!sj||!q){alert('Add a subject and the question.');return;}var b=this;b.disabled=true;
  post({a:'save',id:r.id||0,subject:sj,question:q,sent_to:o.querySelector('#ft').value,sent_to_email:o.querySelector('#fe').value,needed_by:o.querySelector('#fn').value})
  .then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#fm').textContent=x.message||'Could not save.';}});};}
function sendDlg(r){if(!r.sent_to){alert('Add who it is going to first (Edit).');return;}
 var o=dlg('<h2>Mark '+e(r.rfi_no)+' as sent</h2><div class="m">To '+e(r.sent_to)+(r.sent_to_email?' ('+e(r.sent_to_email)+')':'')+'</div><label class="f">Date sent</label><input type="date" id="sd" value="'+today()+'"><div class="note">Tip: use Email it to open your email with the RFI filled in, and attach the RFI PDF.</div><div class="msg" id="sm"></div><div class="b"><button class="btn" id="sg">Mark sent</button><button class="btn ghost" id="sx">Cancel</button></div>');
 guard(o);o.querySelector('#sx').onclick=o.close;
 o.querySelector('#sg').onclick=function(){var b=this;b.disabled=true;post({a:'status',id:r.id,status:'Sent',sent_on:o.querySelector('#sd').value}).then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#sm').textContent=x.message||'Could not save.';}});};}
function answerDlg(r,mode){
 var o=dlg('<h2>'+(mode==='edit'?'Edit answer':'Answer received')+': '+e(r.rfi_no)+'</h2><div class="m">'+e(r.subject)+'</div><label class="f">Answer</label><textarea id="aa" style="min-height:140px">'+e(r.response)+'</textarea><label class="f">Date answered</label><input type="date" id="ad" value="'+e(r.responded_on||today())+'">'+(mode==='edit'?'':'<label class="chk"><input type="checkbox" id="ac"><span>Close the RFI now as well</span></label>')+'<div class="msg" id="am"></div><div class="b"><button class="btn" id="ag">Save</button><button class="btn ghost" id="ax">Cancel</button></div>');
 var start=o.querySelector('#aa').value;function dirty(){return o.querySelector('#aa').value!==start;}
 guard(o,dirty);o.querySelector('#ax').onclick=function(){if(dirty()&&!confirm('Close without saving your changes?'))return;o.close();};
 o.querySelector('#ag').onclick=function(){var t=o.querySelector('#aa').value.trim();if(!t){alert('Enter the answer.');return;}var b=this;b.disabled=true;var c=o.querySelector('#ac');
  var body=mode==='edit'?{a:'answer',id:r.id,response:t,responded_on:o.querySelector('#ad').value}:{a:'status',id:r.id,status:(c&&c.checked)?'Closed':'Answered',response:t,responded_on:o.querySelector('#ad').value};
  post(body).then(function(x){if(x.ok){o.close();load();}else{b.disabled=false;if(!x.cancel)o.querySelector('#am').textContent=x.message||'Could not save.';}});};}
function mail(r){var sub='Job '+JOB+' - '+r.rfi_no+': '+r.subject;var body='Hello,\n\nRequest for information '+r.rfi_no+' for job '+JOB+(D.site?' ('+D.site+')':'')+'.\n\n'+r.question+'\n\n'+(r.needed_by?'Please reply by '+dmy(r.needed_by)+'.\n\n':'')+'Thank you,\nChelmsford Building Services';
 location.href='mailto:'+encodeURIComponent(s(r.sent_to_email))+'?subject='+encodeURIComponent(sub)+'&body='+encodeURIComponent(body);}
function delR(r){if(!confirm('Delete '+r.rfi_no+' ('+r.subject+')?'))return;if(!confirm('Are you sure? This permanently removes the RFI, its answer and its history.'))return;
