function getLogo(){if(LOGO!==null)return Promise.resolve(LOGO);return fetch('/webhook/cbs-programme-logo').then(function(r){return r.json();}).then(function(d){LOGO=(d&&d.lg)||'';return LOGO;}).catch(function(){LOGO='';return '';});}
function head(doc,lg,title,W){doc.setFillColor(244,121,32);doc.rect(0,0,W,3,'F');var lx=14;if(lg){try{var pr=doc.getImageProperties(lg),hh=13,ww=pr.width*hh/pr.height;if(ww>48){ww=48;hh=pr.height*ww/pr.width;}doc.addImage(lg,'PNG',14,7,ww,hh);lx=14+ww+5;}catch(z){}}
 doc.setTextColor(30);doc.setFont('helvetica','bold');doc.setFontSize(15);doc.text(title,lx,12);doc.setFont('helvetica','normal');doc.setFontSize(9);doc.setTextColor(90);doc.text(([D.site,D.client].filter(Boolean).join('  |  ')||'Chelmsford Building Services').slice(0,110),lx,17.5);doc.text('Chelmsford Building Services Ltd  |  '+new Date().toLocaleDateString('en-GB'),W-14,12,{align:'right'});return 28;}
function foot(doc,W,HH){var np=doc.getNumberOfPages();for(var i=1;i<=np;i++){doc.setPage(i);doc.setFontSize(7.5);doc.setTextColor(120);doc.text('Job '+JOB+'  |  Page '+i+' of '+np,W-14,HH-8,{align:'right'});}}
function sheet(r){if(!window.jspdf){alert('The PDF tool did not load. Refresh and try again.');return;}getLogo().then(function(lg){var doc=new window.jspdf.jsPDF({unit:'mm',format:'a4'}),W=210,HH=297,y=head(doc,lg,'Request for information '+r.rfi_no,W);
 function rowL(k,v){if(!s(v))return;doc.setFont('helvetica','bold');doc.setFontSize(9.5);doc.setTextColor(80);doc.text(k,14,y);doc.setFont('helvetica','normal');doc.setTextColor(20);var L=doc.splitTextToSize(s(v),130);doc.text(L,60,y);y+=Math.max(6,L.length*4.6+1.5);}
 function block(t,v){if(!s(v))return;y+=2;if(y>255){doc.addPage();y=20;}doc.setFont('helvetica','bold');doc.setFontSize(10);doc.setTextColor(40);doc.text(t,14,y);y+=5;doc.setFont('helvetica','normal');doc.setFontSize(10);doc.setTextColor(20);doc.splitTextToSize(s(v),182).forEach(function(l){if(y>272){doc.addPage();y=20;}doc.text(l,14,y);y+=4.8;});}
 doc.setFont('helvetica','bold');doc.setFontSize(13);doc.setTextColor(20);var tl=doc.splitTextToSize(s(r.subject),182);doc.text(tl,14,y);y+=tl.length*6+3;
 rowL('Job','Job '+JOB+(D.site?' - '+D.site:''));rowL('To',[r.sent_to,r.sent_to_email].filter(Boolean).join(' - '));rowL('From','Chelmsford Building Services Ltd');rowL('Date sent',dmy(r.sent_on)||'Not sent yet');rowL('Answer needed by',dmy(r.needed_by));rowL('Status',r.status);
