/* RFI data for one job: the log, counts, contacts from Subcontractors and Suppliers, and the job's site/client. */
const h=this.helpers,H='https://old-hub.example/webhook/';
const S=v=>v==null?'':String(v).trim();const jk=v=>S(v).replace(/[^0-9A-Za-z]/g,'').toLowerCase();const num=v=>Number(v)||0;
const q=$input.first().json.query||{};const job=S(q.job).replace(/[^0-9A-Za-z-]/g,'');
const list=async t=>{try{const L=await h.httpRequest({method:'POST',url:H+'cbs-admin-save?a=list&t='+t,body:{},json:true,timeout:30000});return (Array.isArray(L)?L:[]).filter(r=>r&&r.id!=null);}catch(e){return [];}};
if(!job)return [{json:{ok:false,message:'No job number.'}}];
const [V,J,SB,SU]=await Promise.all([list('rfis'),list('jobrows'),list('subbies'),list('suppliers')]);
const today=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).slice(0,10);
const rows=V.filter(r=>jk(r.job_no)===jk(job)).sort((x,y)=>num(S(x.rfi_no).replace(/\D/g,''))-num(S(y.rfi_no).replace(/\D/g,''))||num(x.id)-num(y.id));
rows.forEach(r=>{r.overdue=S(r.status)==='Sent'&&/^\d{4}-\d{2}-\d{2}$/.test(S(r.needed_by))&&S(r.needed_by)<today;});
const jr=J.filter(r=>jk(r.ref)===jk(job)).sort((x,y)=>num(y.id)-num(x.id))[0]||null;
const seen={},contacts=[];
function add(name,company,email){const n=[S(name),S(company)].filter(Boolean);if(!n.length)return;const label=S(name)&&S(company)&&S(name)!==S(company)?S(name)+' ('+S(company)+')':(S(company)||S(name));const k=(label+'|'+S(email)).toLowerCase();if(seen[k])return;seen[k]=1;contacts.push({label:label,email:S(email)});}
SB.forEach(s=>add(s.contact,s.company,s.email));SU.forEach(s=>add(s.contact,s.name,s.email));
if(jr&&S(jr.client))add(S(jr.client_contact),S(jr.client),'');
contacts.sort((a,b)=>a.label.localeCompare(b.label));
const counts={};rows.forEach(r=>{const s=S(r.status)||'Draft';counts[s]=(counts[s]||0)+1;});
return [{json:{ok:true,job:job,today:today,site:S(jr&&jr.site),client:S(jr&&jr.client),rows:rows,counts:counts,overdue:rows.filter(r=>r.overdue).length,contacts:contacts}}];

